  "discussions": [
    {
      "item": "Ordinance 26-013: Nuisance Abatement Property Storage and Disposal Procedures",
      "body": "The Board was scheduled to consider an ordinance amending Section 50.103 of the Municipal Code to establish procedures for the storage and disposal of property removed during nuisance abatement. This ordinance was expected to clarify municipal procedures for handling property in nuisance abatement situations."
    },
    {
      "item": "Ordinance 26-014: Animal Fanciers Code Amendment",
      "body": "The Board was scheduled to consider an ordinance amending Section 10.123 regarding animal fanciers in the Code of Ordinances. This item relates to regulations governing individuals who raise or breed animals within the Village."
    },
    {
      "item": "Joint Resolution 2026-001: Police Department Headquarters Debt Authorization and Intergovernmental Agreement",
      "body": "The Board was scheduled to consider a joint resolution with the Village of Rothschild and Mountain Bay Metropolitan Police Department for debt authorization and an intergovernmental agreement regarding sharing of costs and expenses for construction of a new police department headquarters. This represents a significant capital project involving shared financing between the two villages."
    },
    {
      "item": "Resolution 2026-021: North Central Wisconsin Stormwater Coalition Cooperative Agreement",
      "body": "The Board was scheduled to consider a resolution approving participation in the North Central Wisconsin Stormwater Coalition Cooperative Agreement. This item was set to address the Village's involvement in regional stormwater management efforts."
    },
    {
      "item": "Resolution 2026-022: Bayberry Street and Concord Avenue Reconstruction Project Authorization",
      "body": "The Board was scheduled to consider an authorizing resolution for the Bayberry Street and Concord Avenue Reconstruction Project. This resolution was expected to move forward with street infrastructure improvements in the Village."
    },
    {
      "item": "Establishing 2027 Budget Priorities",
      "body": "The Board was scheduled to discuss and take action on establishing priorities for the 2027 budget. This item was set to guide future financial planning and resource allocation for the Village."
    },
    {
      "item": "Parks and Recreation Committee Recommendation to Continue Farmers Market at Kennedy Park",
      "body": "The Board was scheduled to discuss and take action on a Parks and Recreation Committee recommendation to continue the farmers market at Kennedy Park. This item was expected to address the continuation of this community program."
    },
    {
      "item": "Municipal Center Rooms as Public Meeting/Gathering Spaces and Accompanying Draft Policy",
      "body": "The Board was scheduled to discuss and take action on the use of Municipal Center rooms as public meeting and gathering spaces along with an accompanying draft policy. This item was set to establish guidelines for public use of Village facilities."
    },
    {
      "item": "Rezoning Request: 4205 & 4307 Weston Avenue from B-2 Highway Business to LI Limited Industrial",
      "body": "The Board was scheduled to consider Project #202600263, a rezoning request for properties at 4205 and 4307 Weston Avenue from B-2 Highway Business district to LI Limited Industrial district. The Plan Commission recommended denial of this request, and the Board was expected to review this recommendation."
    },
    {
      "item": "Buchkowski Animal Fancier License at 5512 N. Birch Lane",
      "body": "The Board was scheduled to consider an animal fancier license application for Buchkowski at 5512 North Birch Lane. The Plan Commission recommended denial of this application, and the Board was set to consider this recommendation."
    },
    {
      "item": "Request from Lamar to Purchase a Perpetual Easement at 8702 Progress Way",
      "body": "The Board was scheduled to discuss and take action on a request from Lamar to purchase a perpetual easement over Village-owned real estate at 8702 Progress Way. This item was set to address potential commercial property rights on Village land."
    },
    {
      "item": "President's Appointments to Committees and/or Commissions",
      "body": "The Board was scheduled to discuss and take action on appointments by the President to various Village committees and commissions. This item was expected to fill vacancies or make new appointments to Village boards and committees."
    },
    {
      "item": "Allocation of Everest Metro Police Department and Municipal Court Fund Balance",
      "body": "The Board was scheduled to discuss and take action on the allocation of fund balance from the Everest Metro Police Department and Municipal Court. This item was set to determine how these accumulated funds would be used by the Village."
    },
    {
      "item": "Employee Appreciation, Including Standing Monthly Staff Recognition Agenda Item",
      "body": "The Board was scheduled to discuss and take action on employee appreciation initiatives, including establishing a standing monthly staff recognition agenda item. This item was expected to address ways to recognize and appreciate Village employees."
    },
    {
      "item": "Community Development Authority's Role and Responsibilities Going Forward",
      "body": "The Board was scheduled to discuss and take action regarding the Community Development Authority's role and responsibilities going forward. This item was set to address the future direction and function of this Village authority."
    },
    {
      "item": "Aquatic Center Operational & Capital Costs and Possible Future Municipal/Community Partnerships",
      "body": "The Board was scheduled to discuss and take action on aquatic center operational and capital costs and explore possible future municipal or community partnerships. This item was expected to address the sustainability and future management of the Village's aquatic facility."
    },
    {
      "item": "Policy for Receipt and Handling of Written Comments at Public Meetings",
      "body": "The Board was scheduled to discuss and take action on drafting a policy for the receipt and handling of written comments received at public meetings. This item was set to establish procedures for managing public input submitted in writing."
    },
    {
      "item": "Request for Letter of Support for Greater Wausau Prosperity Partnership's Destination JEM Grant for Ride Wisconsin Gravel",
      "body": "The Board was scheduled to discuss and take action on providing a letter of support for the Greater Wausau Prosperity Partnership's Destination JEM Grant application to the Wisconsin Department of Tourism for the Ride Wisconsin Gravel project. This item was expected to support regional tourism and recreation initiatives."
    },
    {
      "item": "Contract for Final TIF#1 Audit",
      "body": "The Board was scheduled to discuss and take action on a contract for the final audit of Tax Increment Finance District #1. This item was set to complete the financial review of this development district."
    },
    {
      "item": "Bank Proposals for Village's Portion of New Police Headquarters",
      "body": "The Board was scheduled to discuss and take action on bank proposals for financing the Village's portion of the new police headquarters construction. This item was expected to review financing options for the significant capital project."
    }
  ],
